import * as z from "zod/v4";
import { defineTool } from "../../../tools.js";
import extension from "../extension.js";
import { cloudAgentsBackend } from "../lib/backend.js";
import { assertWriteChannel } from "../lib/channels.js";
import { assertOwned } from "../lib/fleet.js";
import { agentRef } from "../lib/inputs.js";
const reply = defineTool({
    description: "Send a follow-up prompt to a cloud agent you launched. It queues behind the current run; pass interrupt to stop that run's current step and deliver it now.",
    effect: "write",
    needsApproval: () => extension.config.needsApproval,
    inputSchema: agentRef.extend({
        prompt: z.string().min(1).describe("The follow-up instruction."),
        interrupt: z
            .boolean()
            .default(false)
            .describe("Deliver now, cancelling the in-flight step, instead of waiting for the current run to finish."),
    }),
    async execute(input, ctx) {
        assertWriteChannel(ctx);
        await assertOwned(ctx, input.agent_id);
        const { runId } = await cloudAgentsBackend().followUp(input.agent_id, input.prompt, input.interrupt);
        return { agentId: input.agent_id, runId, queued: !input.interrupt };
    },
});
export default reply;
